#include <iostream>
#include <vector>
#include <string>
using namespace std;


// 处理一组测试数据，返回需要翻转的下标
vector<int> solveOne(int n, const string &s) {
    vector<int> st;        // 存未匹配的 '(' 下标
    vector<int> badRight;  // 存未匹配的 ')' 下标

    for (int i = 0; i < n; i++) {
        char ch = s[i];
        int idx = i + 1;   // 题目下标从 1 开始

        if (ch == '(') {
            st.push_back(idx);
        } else {
            if (!st.empty()) {
                st.pop_back(); // 匹配掉一对括号
            } else {
                badRight.push_back(idx);
            }
        }
    }

    vector<int> ans;
    int a = (int)badRight.size();
    int b = (int)st.size();

    // 翻转最前面的 ceil(a / 2) 个未匹配 ')'
    int needRight = (a + 1) / 2;
    for (int i = 0; i < needRight; i++) {
        ans.push_back(badRight[i]);
    }

    // 翻转最后面的 ceil(b / 2) 个未匹配 '('
    int needLeft = (b + 1) / 2;
    for (int i = b - needLeft; i < b; i++) {
        ans.push_back(st[i]);
    }

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;

    while (T--) {
        int n;
        string s;
        cin >> n >> s;

        vector<int> ans = solveOne(n, s);

        cout << ans.size() << '\n';
        if (ans.empty()) {
            cout << '\n';
        } else {
            for (int i = 0; i < (int)ans.size(); i++) {
                if (i) cout << ' ';
                cout << ans[i];
            }
            cout << '\n';
        }
    }

    return 0;
}
